#!/usr/bin/env python3
"""TASK-4: Create src/cargo_info.rs with parse_cargo_toml"""
import base64, json, sys
from pathlib import Path

TASK_ID = "TASK-4"
STEPS = json.loads('[{"content_b64": "", "target": "src/cargo_info.rs", "index": 0}]')

for step in STEPS:
    content = base64.b64decode(step["content_b64"]).decode()
    target = step["target"]
    idx = step["index"]

    target_path = Path(target)
    target_path.parent.mkdir(parents=True, exist_ok=True)
    target_path.write_text(content)

    if not target_path.exists():
        print(f"FAILED {TASK_ID} change {idx}: file not created at {target}", file=sys.stderr)
        sys.exit(1)

    print(f"OK {TASK_ID} change {idx}: created {target}")

print(f"OK {TASK_ID}: all files created")
